/*
 * A289287  Starting with a(1) = 1, a(n) = smallest nonnegative integer not
 *          yet in the sequence such that the last digit of a(n-1) plus the
 *          first digit of a(n) is equal to 9. The digit 0 is not allowed.
 * https://oeis.org/A289287
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   Recursively generated by the definition of A289287. a(1) = 1.
 *            a(n) = smallest nonnegative integer not yet in the sequence such
 *            that the last digit of a(n-1) plus the first digit of a(n)
 *            equals 9. Numbers containing the digit 0 are forbidden
 * Range:     u8 n <= 73, u16 n <= 73, u32 n <= 73, u64 n <= 73, u128 n <= 73,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* Helper: test whether a number contains the digit 0. */
static bool has_zero_digit(seq_t x) {
    if (x == 0) return true;                 /* single digit 0 */
    while (x > 0) {
        if (x % (seq_t)10 == 0) return true;
        x /= (seq_t)10;
    }
    return false;
}

/* Helper: extract the first (most significant) digit of a number. */
static seq_t first_digit(seq_t x) {
    while (x >= (seq_t)10) {
        x /= (seq_t)10;
    }
    return x;
}

/* The cached sequence and its state. */
static seq_t *cache = NULL;          /* array of terms */
static size_t cache_len = 0;         /* number of terms generated */
static size_t cache_cap = 0;         /* capacity of the array */

/* Ensure the array has space for at least 'need' terms. */
static void ensure_capacity(size_t need) {
    if (cache_cap >= need) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 8;
    if (new_cap < need) new_cap = need;
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    cache = tmp;
    cache_cap = new_cap;
}

/* Generate terms up to index n (1‑based). */
static void generate_upto(idx_t n) {
    if (n == 0) return;
    size_t target = (size_t)n;
    if (cache_len >= target) return;

    ensure_capacity(target);

    /* Initialize the first term. */
    if (cache_len == 0) {
        cache[0] = (seq_t)1;
        cache_len = 1;
    }

    while (cache_len < target) {
        seq_t last = cache[cache_len - 1];
        seq_t last_digit = last % (seq_t)10;
        seq_t needed_first = 9 - last_digit;   /* 1..8 */

        /* Search candidate numbers. */
        seq_t cand = 1;           /* start from 1; 0 is disallowed */
        for (;;) {
            /* skip numbers containing 0 */
            if (!has_zero_digit(cand)) {
                /* first digit check */
                if (first_digit(cand) == needed_first) {
                    /* uniqueness check */
                    bool used = false;
                    for (size_t i = 0; i < cache_len; ++i) {
                        if (cache[i] == cand) {
                            used = true;
                            break;
                        }
                    }
                    if (!used) {
                        cache[cache_len] = cand;
                        cache_len++;
                        break;    /* found next term */
                    }
                }
            }
            cand++;    /* try next integer */
        }
    }
}

seq_t a(idx_t n) {
    /* The sequence is finite (73 terms). If n is beyond that,
       the behaviour is undefined; we simply return 0. */
    if (n == 0) return (seq_t)0;
    if ((idx_t)73 < n) return (seq_t)0;
    generate_upto(n);
    return cache[(size_t)n - 1];
}
